'use client';

interface CardProps {
  experience: ExperienceType;
}
export default function Card({ experience }: CardProps) {
    const date = new Date(experience.dates[0]);
    console.log(date.toLocaleDateString("en-US"), {
        month: "full",
        day: "numeric",
        year: "numeric",
    })
    const dates = experience.dates.map(date => (new Date(date)).toLocaleDateString("en-US", {month: "short", day: "numeric", year: "numeric"}));


    return (
        <div className="rounded-4xl bg-[var(--background)] text-[var(--foreground)] w-[60vw] lg:w-[30vw] xl:w-[20vw] aspect-[5/2] lg:aspect-square bubble flex flex-row lg:flex-col items-center justify-between">
            <img src={experience.images[0].url} alt={experience.images[0].caption} className="object-cover h-full w-auto lg:h-auto lg:w-full overflow-clip aspect-square lg:aspect-[3/2] rounded-l-4xl lg:rounded-t-4xl lg:rounded-bl-none"/>
            <div className="flex-1 w-full text-left font-sans p-2 px-3">
                <h1 className="font-bold [font-size:_clamp(10px, 4vw, 200px)]">{experience.title}</h1>
                <p className="text-sm">{dates.join(" - ")}</p>
                <p className="text-sm">{experience.description}</p>
            </div>
        </div>
    );
}